   218	 *
   219	 * The admin sidebar must mirror the public hub sidebar: Thư viện stops at
   220	 * kind → lv1 → lv2, and Bản tin stops at lv1 → lv2.
   221	 *
   222	 * @return array{sections:array<int,array<string,mixed>>}
   223	 */
   224	function read_public_taxonomy_tree(): array
   225	{
   226	  $path = dirname(dirname(__DIR__)) . '/data/taxonomy.json';
   227	  if (!file_exists($path)) {
   228	    return ['sections' => []];
   229	  }
   230	
   231	  $raw = file_get_contents($path);
   232	  if ($raw === false || trim($raw) === '') {
   233	    return ['sections' => []];
   234	  }
   235	
   236	  $decoded = json_decode($raw, true);
   237	  if (!is_array($decoded) || !is_array($decoded['roots'] ?? null)) {
   238	    return ['sections' => []];
   239	  }
   240	
   241	  $sections = [];
   242	  foreach ($decoded['roots'] as $root) {
   243	    if (!is_array($root)) {
   244	      continue;
   245	    }
   246	    $sectionKey = trim((string) ($root['key'] ?? ($root['id'] ?? '')));
   247	    if ($sectionKey === '') {
