   249	    }
   250	
   251	    $sectionNode = public_taxonomy_base_node($root, 'section');
   252	    $sectionNode['children'] = [];
   253	    $children = is_array($root['children'] ?? null) ? $root['children'] : [];
   254	
   255	    if ($sectionKey === 'thu-vien') {
   256	      foreach ($children as $kind) {
   257	        if (is_array($kind)) {
   258	          $sectionNode['children'][] = normalize_public_taxonomy_branch($kind, 'library_kind', 2);
