   182	/**
   183	 * Extract `<script id="article-meta">...</script>` region.
   184	 *
   185	 * @return array<string,mixed>
   186	 */
   187	function extract_article_meta_region(string $html): array
   188	{
   189	  if (!preg_match('/<script\b[^>]*id=(["\'])article-meta\1[^>]*>/is', $html, $match, PREG_OFFSET_CAPTURE)) {
   190	    return [
   191	      'ok' => false,
   192	      'code' => 'missing_article_meta_script',
   193	      'message' => 'Không tìm thấy script#article-meta.',
   194	    ];
   195	  }
   196	
   197	  $openTag = (string) $match[0][0];
   198	  $openOffset = (int) $match[0][1];
   199	  $openEnd = $openOffset + strlen($openTag);
   200	
   201	  $closeOffset = stripos($html, '</script>', $openEnd);
   202	  if ($closeOffset === false) {
   203	    return [
   204	      'ok' => false,
   205	      'code' => 'missing_article_meta_close',
   206	      'message' => 'Không tìm thấy thẻ đóng của script#article-meta.',
   207	    ];
   208	  }
   209	
   210	  $inner = substr($html, $openEnd, $closeOffset - $openEnd);
   211	  if ($inner === false) {
   212	    $inner = '';
   213	  }
   214	
   215	  return [
   216	    'ok' => true,
   217	    'start' => $openOffset,
   218	    'open_tag_end' => $openEnd,
   219	    'close_tag_start' => $closeOffset,
   220	    'end' => $closeOffset + strlen('</script>'),
   221	    'open_tag' => $openTag,
   222	    'close_tag' => '</script>',
   223	    'inner' => trim($inner),
   224	    'inner_length' => strlen(trim($inner)),
   225	  ];
   226	}
