   228	/**
   229	 * Extract summary from `<p class="article-summary">`.
   230	 */
   231	function extract_article_summary_text(string $html): string
   232	{
   233	  if (!preg_match('/<p\b[^>]*class=(["\'])(?:(?!\1).)*\barticle-summary\b(?:(?!\1).)*\1[^>]*>(.*?)<\/p>/is', $html, $match)) {
   234	    return '';
   235	  }
   236	  $inner = trim((string) ($match[2] ?? ''));
